# AMP: points mission_save at the newest save made in the configured campaign mode, or clears it so a new map starts.
param([string]$Config, [string]$Saves)
$text = [IO.File]::ReadAllText($Config)
if ($text -notmatch '(?m)^set campaign "(.*)"') { exit 0 }
$mode = 'campaigns/' + $Matches[1] + '.campaign'
$inf = Get-ChildItem -Path $Saves -Filter *.inf -Recurse -ErrorAction SilentlyContinue | Where-Object { [IO.File]::ReadAllText($_.FullName).Contains($mode) } | Sort-Object LastWriteTime | Select-Object -Last 1
$name = ''
if ($inf) { $name = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($inf.BaseName.Replace('-', '+').Replace('_', '/'))) }
[IO.File]::WriteAllText($Config, ($text -replace '(?m)^set mission_save ".*"', ('set mission_save "' + $name.Replace('$', '$$') + '"')))
if ($name) { Write-Output "[AMP] Loading latest save: $name" } else { Write-Output '[AMP] No saves for this campaign mode, starting a new map' }
